var B=$('Run hook').first().json.body||{};
if(B.secret!=='onb-rc-2026-09-30-Wq8'){throw new Error('bad secret');}
var IDX={E:4,O:14,AD:29,AE:30,AF:31,AG:32,AH:33,AI:34,AJ:35,AK:36,AL:37};
var PLAN=Array.isArray(B.plan)?B.plan:[];
if(!PLAN.length){throw new Error('empty plan');}
if(PLAN.length>60){throw new Error('plan too large: '+PLAN.length);}
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');}
var sh=$('Read ONBOARDING').first().json||{};
var rows=sh.values||[];
if(!rows.length){return [{json:{fatal:'ONBOARDING read returned no values',planned:0}}];}
var data=[],audit=[];
for(var i=0;i<PLAN.length;i++){
  var p=PLAN[i];var rn=Number(p.row);
  if(!Number.isInteger(rn)||rn<2||rn>900){audit.push({row:p.row,firm:p.firm,result:'SKIPPED - bad row number'});continue;}
  var r=rows[rn-1]||[];
  if(!r.length){audit.push({row:rn,firm:p.firm,result:'SKIPPED - row not found'});continue;}
  if(norm(String(r[5]||''))!==norm(p.firm)){audit.push({row:rn,firm:p.firm,result:'SKIPPED - firm mismatch, sheet says "'+String(r[5]||'')+'"'});continue;}
  var force=Array.isArray(p.force)?p.force:[];
  var cells=p.cells||{};var wrote=[],skipped=[];
  for(var c in cells){
    if(!IDX.hasOwnProperty(c)){skipped.push(c+' (column not writable)');continue;}
    var val=String(cells[c]);
    if(!val.length){skipped.push(c+' (empty value)');continue;}
    var cur=String(r[IDX[c]]||'').trim();
    var forced=force.indexOf(c)>-1;
    if(cur&&!forced){skipped.push(c+' (already "'+cur.slice(0,40)+'")');continue;}
    if(cur&&forced&&cur===val){skipped.push(c+' (already equals target)');continue;}
    data.push({range:'ONBOARDING!'+c+rn,values:[[val]]});
    wrote.push(c+(cur?' (overwrote "'+cur.slice(0,30)+'" as instructed)':''));
  }
  var mode=p.noteMode||'append';
  if(mode!=='none'&&p.note){
    var curO=String(r[IDX.O]||'').trim();var nv=null;
    if(!curO){nv=String(p.note);}
    else if(mode==='append'){
      if(p.noteKey&&curO.indexOf(p.noteKey)>-1){skipped.push('O (already recorded, key '+p.noteKey+')');}
      else{nv=curO+'  |  '+String(p.note);}
    }
    else{skipped.push('O (non-empty, mode=set, left intact)');}
    if(nv!==null){data.push({range:'ONBOARDING!O'+rn,values:[[nv]]});wrote.push(curO?'O (appended)':'O');}
  }
  audit.push({row:rn,firm:p.firm,outcome:cells.AK||'',wrote:wrote,skipped:skipped});
}
return [{json:{planned:data.length,audit:audit,body:{valueInputOption:'RAW',data:data}}}];

var b=$('Build').first().json||{};
var w=null;try{w=$('Write').first().json;}catch(e){w=null;}
var ranges=(((b.body||{}).data)||[]).map(function(d){return d.range;});
return [{json:{planned:b.planned||0,cellsUpdated:w?(w.totalUpdatedCells||0):0,rangesSent:ranges,writeOk:!!w,audit:b.audit||[]}}];
